sys_ui_page.client_script:
window.addEventListener(
    'load',
    function() {
        loadTeamAttendance();
    }
);


// =============================================================
// LOAD TEAM ATTENDANCE
// =============================================================
function loadTeamAttendance() {

    var loadingBox =
        document.getElementById('loadingBox');

    var teamContainer =
        document.getElementById('teamContainer');


    fetch(
        '/api/x_1760545_smarta_0/smartattend_api/team-attendance',
        {
            method: 'GET',

            credentials: 'same-origin',

            headers: {
                'X-UserToken':
                    window.g_ck || ''
            }
        }
    )

    .then(function(response) {

        return response
            .json()
            .then(function(data) {

                return {
                    ok: response.ok,
                    data: data
                };

            });

    })

    .then(function(result) {

        if (
            !result.ok ||
            !result.data.result ||
            !result.data.result.success
        ) {

            throw new Error(
                'Unable to load team attendance.'
            );
        }


        var data =
            result.data.result;


        // -----------------------------------------------------
        // Manager header
        // -----------------------------------------------------
        document.getElementById(
            'managerName'
        ).innerHTML =
            data.manager || 'Manager';


        document.getElementById(
            'managerDate'
        ).innerHTML =
            formatDate(
                data.attendance_date
            );


        document.getElementById(
            'managerBar'
        ).style.display =
            'block';


        // -----------------------------------------------------
        // Summary counts
        // -----------------------------------------------------
        var total = 0;
        var present = 0;
        var late = 0;
        var missing = 0;


        if (data.employees) {

            total =
                data.employees.length;


            for (
                var i = 0;
                i < data.employees.length;
                i++
            ) {

                var status =
                    data.employees[i]
                        .attendance
                        .status;


                if (status === 'present') {
                    present++;
                }

                else if (status === 'late') {
                    late++;
                }

                else if (
                    status ===
                    'not_checked_in'
                ) {

                    missing++;
                }
            }
        }


        document.getElementById(
            'totalCount'
        ).innerHTML =
            total;


        document.getElementById(
            'presentCount'
        ).innerHTML =
            present;


        document.getElementById(
            'lateCount'
        ).innerHTML =
            late;


        document.getElementById(
            'missingCount'
        ).innerHTML =
            missing;


        document.getElementById(
            'summaryGrid'
        ).style.display =
            'grid';


        loadingBox.style.display =
            'none';


        // -----------------------------------------------------
        // No employees
        // -----------------------------------------------------
        if (
            !data.employees ||
            data.employees.length === 0
        ) {

            teamContainer.innerHTML =
                '<div class="employee-card">' +
                    'No employees are assigned to this manager.' +
                '</div>';

            return;
        }


        // -----------------------------------------------------
        // Render employees
        // -----------------------------------------------------
        var html = '';


        for (
            var j = 0;
            j < data.employees.length;
            j++
        ) {

            html +=
                buildEmployeeCard(
                    data.employees[j]
                );
        }


        teamContainer.innerHTML =
            html;

    })

    .catch(function(error) {

        console.error(
            'Team Attendance Error:',
            error
        );


        loadingBox.className =
            'error';


        loadingBox.innerHTML =
            error.message ||
            'Unable to load team attendance.';

    });
}



// =============================================================
// BUILD EMPLOYEE CARD
// =============================================================
function buildEmployeeCard(
    employee
) {

    var attendance =
        employee.attendance || {};


    var statusText =
        formatStatus(
            attendance.status
        );


    var statusClass =
        getStatusClass(
            attendance.status
        );


    var employeeCode =
        employee.employee_code ||
        'No Employee Code';


    var department =
        employee.department ||
        'No Department';


    var shift =
        employee.shift ||
        '-';


    var checkIn =
        formatDateTime(
            attendance.check_in
        );


    var checkOut =
        formatDateTime(
            attendance.check_out
        );


    return (

        '<div class="employee-card">' +

            '<div class="employee-top">' +

                '<div>' +

                    '<div class="employee-name">' +
                        escapeHtml(
                            employee.employee || '-'
                        ) +
                    '</div>' +

                    '<div class="employee-meta">' +
                        escapeHtml(employeeCode) +
                        ' • ' +
                        escapeHtml(department) +
                        ' • ' +
                        escapeHtml(shift) +
                    '</div>' +

                '</div>' +

                '<div class="status-badge ' +
                    statusClass +
                '">' +

                    escapeHtml(
                        statusText
                    ) +

                '</div>' +

            '</div>' +


            '<div class="details-grid">' +

                buildDetailBox(
                    'Check In',
                    checkIn || '-'
                ) +

                buildDetailBox(
                    'Check Out',
                    checkOut || '-'
                ) +

                buildDetailBox(
                    'Late Minutes',
                    attendance.late_minutes || '0'
                ) +

                buildDetailBox(
                    'Working Minutes',
                    attendance.working_minutes || '-'
                ) +

            '</div>' +

        '</div>'
    );
}



// =============================================================
// DETAIL BOX
// =============================================================
function buildDetailBox(
    label,
    value
) {

    return (

        '<div class="detail-box">' +

            '<div class="detail-label">' +
                escapeHtml(label) +
            '</div>' +

            '<div class="detail-value">' +
                escapeHtml(
                    String(value)
                ) +
            '</div>' +

        '</div>'
    );
}



// =============================================================
// FORMAT STATUS
// =============================================================
function formatStatus(status) {

    if (status === 'present') {
        return 'Present';
    }

    if (status === 'late') {
        return 'Late';
    }

    if (status === 'half_day') {
        return 'Half Day';
    }

    if (
        status ===
        'insufficient_hours'
    ) {
        return 'Insufficient Hours';
    }

    if (
        status ===
        'not_checked_in'
    ) {
        return 'Not Checked In';
    }

    return status || '-';
}



// =============================================================
// STATUS CLASS
// =============================================================
function getStatusClass(status) {

    if (status === 'present') {
        return 'status-present';
    }

    if (status === 'late') {
        return 'status-late';
    }

    if (status === 'half_day') {
        return 'status-half';
    }

    if (
        status ===
        'not_checked_in'
    ) {
        return 'status-missing';
    }

    return 'status-insufficient';
}



// =============================================================
// FORMAT DATE
// =============================================================
function formatDate(dateValue) {

    if (!dateValue) {
        return '-';
    }


    var parts =
        dateValue.split('-');


    if (parts.length !== 3) {
        return dateValue;
    }


    return (
        parts[2] +
        '-' +
        parts[1] +
        '-' +
        parts[0]
    );
}



// =============================================================
// FORMAT DATETIME
// =============================================================
function formatDateTime(dateTime) {

    if (!dateTime) {
        return '';
    }


    var parts =
        dateTime.split(' ');


    if (parts.length < 2) {
        return dateTime;
    }


    return parts[1];
}



// =============================================================
// HTML ESCAPE
// =============================================================
function escapeHtml(value) {

    return String(value)

        .replace(/&/g, '&amp;')

        .replace(/</g, '&lt;')

        .replace(/>/g, '&gt;')

        .replace(/"/g, '&quot;')

        .replace(/'/g, '&#039;');
}
